BEGIN;
CREATE TABLE IF NOT EXISTS public.restaurants (
 id SERIAL PRIMARY KEY, name TEXT NOT NULL, address TEXT, ward TEXT, district TEXT, cuisine TEXT NOT NULL,
 "notableDishes" TEXT[] NOT NULL DEFAULT '{}', "imagePath" TEXT, "photoType" TEXT, "priceMinVnd" INTEGER, "priceMaxVnd" INTEGER,
 "michelinUrl" TEXT NOT NULL UNIQUE, "searchText" TEXT NOT NULL DEFAULT '', "verifiedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE public.restaurants ALTER COLUMN "michelinUrl" DROP NOT NULL;
CREATE TABLE IF NOT EXISTS public.stories (id SERIAL PRIMARY KEY, name TEXT NOT NULL, location TEXT NOT NULL, initials TEXT NOT NULL, text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS public.restaurant_import_archive ("legacyId" INTEGER PRIMARY KEY, record JSONB NOT NULL, "archivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE public.dishes ALTER COLUMN price DROP NOT NULL;
ALTER TABLE public.dishes ADD COLUMN IF NOT EXISTS "searchText" TEXT NOT NULL DEFAULT '';
ALTER TABLE public.dishes ADD COLUMN IF NOT EXISTS "importKey" TEXT;
ALTER TABLE public.dishes ADD COLUMN IF NOT EXISTS "restaurantId" INTEGER REFERENCES public.restaurants(id) ON DELETE SET NULL;
CREATE UNIQUE INDEX IF NOT EXISTS dishes_importKey_key ON public.dishes ("importKey");
CREATE INDEX IF NOT EXISTS dishes_restaurantId_idx ON public.dishes ("restaurantId");

-- Preserve exact original records before moving restaurant rows out of dishes.
INSERT INTO public.restaurant_import_archive ("legacyId", record)
SELECT id, to_jsonb(d) FROM public.dishes d WHERE "michelinUrl" IS NOT NULL AND "restaurantId" IS NULL AND "importKey" IS NULL
ON CONFLICT ("legacyId") DO NOTHING;
INSERT INTO public.restaurants (id,name,cuisine,"imagePath","photoType","priceMinVnd","priceMaxVnd","michelinUrl")
SELECT id,name,COALESCE(category,'Ẩm thực Việt'),"imagePath","photoType","priceMinVnd","priceMaxVnd","michelinUrl"
FROM public.dishes WHERE "michelinUrl" IS NOT NULL AND "restaurantId" IS NULL AND "importKey" IS NULL
ON CONFLICT ("michelinUrl") DO NOTHING;
DELETE FROM public.dishes d USING public.restaurant_import_archive a
WHERE d.id=a."legacyId" AND to_jsonb(d)=a.record AND d."michelinUrl" IS NOT NULL;
SELECT setval(pg_get_serial_sequence('public.dishes','id'), GREATEST(COALESCE((SELECT MAX(id) FROM public.dishes),1),1),true);
-- Quoted identifiers and parameters are used by app queries; no request text is interpolated into SQL.
CREATE OR REPLACE FUNCTION public.catalog_normalize(value TEXT) RETURNS TEXT
LANGUAGE SQL IMMUTABLE PARALLEL SAFE AS $$
 SELECT trim(regexp_replace(regexp_replace(replace(lower(normalize(COALESCE(value,''), NFD)), 'đ', 'd'), '[̀-ͯ]', '', 'g'), '[^a-z0-9]+', ' ', 'g'))
$$;
CREATE OR REPLACE FUNCTION public.restaurant_search_index() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
 NEW."searchText" := catalog_normalize(concat_ws(' ', NEW.name, NEW.address, NEW.ward, NEW.district, NEW.cuisine,
 array_to_string(NEW."notableDishes",' '),
 CASE NEW.cuisine WHEN 'Vegetarian' THEN 'món chay rau chay' WHEN 'Noodles' THEN 'món nước'
 WHEN 'Street Food' THEN 'món ăn vặt' WHEN 'Vietnamese' THEN 'ẩm thực Việt'
 WHEN 'Vietnamese Contemporary' THEN 'ẩm thực Việt hiện đại' WHEN 'Cantonese' THEN 'món Hoa Quảng Đông'
 WHEN 'Seafood' THEN 'hải sản' WHEN 'Fish and Seafood' THEN 'cá hải sản' ELSE '' END,
 (SELECT string_agg(name,' ') FROM dishes WHERE "restaurantId"=NEW.id)));
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS restaurant_search_index ON public.restaurants;
CREATE TRIGGER restaurant_search_index BEFORE INSERT OR UPDATE ON public.restaurants FOR EACH ROW EXECUTE FUNCTION public.restaurant_search_index();
CREATE OR REPLACE FUNCTION public.dish_search_index() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$
BEGIN NEW."searchText" := catalog_normalize(concat_ws(' ',NEW.name,NEW.category)); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS dish_search_index ON public.dishes;
CREATE TRIGGER dish_search_index BEFORE INSERT OR UPDATE ON public.dishes FOR EACH ROW EXECUTE FUNCTION public.dish_search_index();
CREATE OR REPLACE FUNCTION public.refresh_restaurant_search() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
 IF TG_OP <> 'INSERT' AND OLD."restaurantId" IS NOT NULL THEN UPDATE restaurants SET name=name WHERE id=OLD."restaurantId"; END IF;
 IF TG_OP <> 'DELETE' AND NEW."restaurantId" IS NOT NULL THEN UPDATE restaurants SET name=name WHERE id=NEW."restaurantId"; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS refresh_restaurant_search ON public.dishes;
CREATE TRIGGER refresh_restaurant_search AFTER INSERT OR UPDATE OR DELETE ON public.dishes FOR EACH ROW EXECUTE FUNCTION public.refresh_restaurant_search();
