UPDATE public.restaurants SET name=name;
SELECT setval(pg_get_serial_sequence('public.restaurants','id'), GREATEST(COALESCE((SELECT MAX(id) FROM public.restaurants),1),1),true);
SELECT setval(pg_get_serial_sequence('public.dishes','id'), GREATEST(COALESCE((SELECT MAX(id) FROM public.dishes),1),(SELECT last_value FROM public.dishes_id_seq)),true);
